/**
 * MIRA — Validate Agent Outputs
 * Version: 3.2
 *
 * n8n Code node
 * Mode: Run Once for All Items
 *
 * Validation scope:
 * - Agent output presence
 * - Structural completeness
 * - Internal consistency
 * - Source-reference presence
 *
 * Does NOT independently verify source facts.
 */

const ctx = $('Build Project Context').first().json || {};
const runId = String($execution.id || '');

const allAgents = [
  'plan',
  'risk',
  'status',
  'milestone',
  'stakeholder_update'
];

const sources = {
  plan: 'Planner Agent',
  risk: 'Risk Assessor Agent',
  status: 'Status Reporter Agent',
  milestone: 'Milestone Tracker Agent',
stakeholder_update: 'Stakeholder Update Agent'
};

// --------------------------------------------------
// 1. NORMALIZE CAPABILITIES
// --------------------------------------------------

function normalizeCapabilities(raw) {
  let value = raw;

  if (value === null || value === undefined) {
    throw new Error('Capabilities were not provided');
  }

  if (typeof value === 'string') {
    const s = value.trim();

    if (!s) {
      throw new Error('Capabilities are empty');
    }

    if (s.startsWith('[')) {
      try {
        value = JSON.parse(s);
      } catch (e) {
        throw new Error(
          'Invalid capabilities JSON: ' + s
        );
      }
    } else {
      value = s.split(',');
    }
  }

  const result = (
    Array.isArray(value) ? value : [value]
  )
    .map(x => String(x).trim().toLowerCase())
    .filter(Boolean);

  if (result.includes('all')) {
    return [...allAgents];
  }

  const invalid = result.filter(
    x => !allAgents.includes(x)
  );

  if (invalid.length > 0) {
    throw new Error(
      'Unsupported capabilities: ' +
      invalid.join(', ')
    );
  }

  if (result.length === 0) {
    throw new Error('No capabilities selected');
  }

  return [...new Set(result)];
}

const wanted = normalizeCapabilities(
  ctx.capabilities ?? ctx.request_type
);

console.log(
  'MIRA requested capabilities:',
  JSON.stringify(wanted)
);

// --------------------------------------------------
// 2. COMMON HELPERS
// --------------------------------------------------

const isArray = Array.isArray;

const nonEmpty = value =>
  value !== null &&
  value !== undefined &&
  String(value).trim() !== '';

const hasSource = value =>
  nonEmpty(value) &&
  String(value).trim().toLowerCase() !==
    'unspecified';

const normalizeStatus = value =>
  String(value || '')
    .trim()
    .toLowerCase()
    .replace(/[\s-]+/g, '_');

function pick(name) {
  try {
    if (!$(name).isExecuted) {
      return null;
    }

    const item = $(name).first();

    return item && item.json
      ? item.json
      : null;
  } catch (e) {
    return null;
  }
}



function unwrapAgentOutput(raw) {
  if (!raw || typeof raw !== 'object') {
    return raw;
  }

  let value = raw.output ?? raw;

  if (typeof value === 'string') {
    const clean = value.trim()
      .replace(/^```(?:json)?\s*/i, '')
      .replace(/```\s*$/i, '');

    try {
      value = JSON.parse(clean);
    } catch (e) {
      return {
        status: 'error',
        error_detail: 'AI Agent returned invalid JSON.',
        raw_output: value
      };
    }
  }

  if (
    value &&
    typeof value === 'object' &&
    !Array.isArray(value)
  ) {
    return value;
  }

  return {
    status: 'error',
    error_detail: 'AI Agent returned no valid JSON object.'
  };
}


function getReport(o, key) {
  if (!o || typeof o !== 'object') {
    return {};
  }

  if (
    key === 'plan' &&
    o.plan &&
    typeof o.plan === 'object'
  ) {
    return o.plan;
  }

  return o;
}

// --------------------------------------------------
// 3. PLANNER VALIDATION
// --------------------------------------------------

function validatePlan(o) {
  const issues = [];
  const p = o.plan || {};

  if (
    !o.plan ||
    typeof o.plan !== 'object' ||
    Array.isArray(o.plan)
  ) {
    issues.push('plan object missing');
    return issues;
  }

  if (!isArray(p.phases)) {
    issues.push('phases array missing');
  } else if (p.phases.length === 0) {
    issues.push('plan has no phases');
  }

  if (!isArray(p.milestones)) {
    issues.push('milestones array missing');
  } else {
    p.milestones.forEach((m, i) => {
      if (!m || typeof m !== 'object') {
        issues.push(
          `plan milestone ${i + 1} is invalid`
        );
        return;
      }

      if (!nonEmpty(m.name)) {
        issues.push(
          `plan milestone ${i + 1} has no name`
        );
      }

      if (!hasSource(m.source_reference)) {
        issues.push(
          `plan milestone ${
            m.name || i + 1
          } has no source reference`
        );
      }

      if (
        m.target_week !== null &&
        m.target_week !== undefined &&
        (
          !Number.isInteger(Number(m.target_week)) ||
          Number(m.target_week) < 1
        )
      ) {
        issues.push(
          `plan milestone ${
            m.name || i + 1
          } has invalid target_week`
        );
      }
    });
  }

  return issues;
}

// --------------------------------------------------
// 4. RISK VALIDATION
// --------------------------------------------------

function validateRisk(o) {
  const issues = [];

  if (!isArray(o.risks)) {
    issues.push('risks array missing');
    return issues;
  }

  const riskIds = new Set();

  o.risks.forEach((r, i) => {
    if (!r || typeof r !== 'object') {
      issues.push(`risk ${i + 1} is invalid`);
      return;
    }

    const id = String(r.risk_id || '').trim();

    if (!id) {
      issues.push(`risk ${i + 1} has no risk_id`);
    } else if (riskIds.has(id)) {
      issues.push(`duplicate risk_id: ${id}`);
    } else {
      riskIds.add(id);
    }

    if (!nonEmpty(r.risk_challenge)) {
      issues.push(
        `risk ${id || i + 1} has no risk challenge`
      );
    }

    if (!nonEmpty(r.category)) {
      issues.push(
        `risk ${id || i + 1} has no category`
      );
    }

    if (!nonEmpty(r.impact)) {
      issues.push(
        `risk ${id || i + 1} has no impact`
      );
    }

    if (!nonEmpty(r.mitigation_strategy)) {
      issues.push(
        `risk ${id || i + 1} has no mitigation strategy`
      );
    }

    if (!hasSource(r.source_reference)) {
      issues.push(
        `risk ${id || i + 1} has no source reference`
      );
    }
  });

  if (isArray(o.top_risk_ids)) {
    o.top_risk_ids.forEach(id => {
      if (!riskIds.has(String(id))) {
        issues.push(
          `top risk ${id} not present in risks`
        );
      }
    });
  }

  // Numeric severity is not mandatory
  // when the source does not contain scores.

  return issues;
}

// --------------------------------------------------
// 5. STATUS VALIDATION
// --------------------------------------------------


function validateStatus(o) {
  const issues = [];
  const isObj = x =>
    x !== null &&
    typeof x === 'object' &&
    !Array.isArray(x);

  const str = x => String(x ?? '').trim();
  const list = x => Array.isArray(x) ? x : [];

  // ---------------------------------------------
  // 1. Required report structure
  // ---------------------------------------------

  if (!isObj(o)) {
    return ['status report is not a JSON object'];
  }

  if (!nonEmpty(o.project_name)) {
    issues.push('project_name missing');
  }

  const summary = o.summary ?? o.executive_summary;

  if (!nonEmpty(summary)) {
    issues.push('status summary missing');
  }

  if (!isArray(o.tasks)) {
    issues.push('tasks array missing');
    return issues;
  }

  const tasks = o.tasks;
  const ids = new Set();

  const actual = {
    Done: 0,
    'In Progress': 0,
    'To Do': 0,
    Blocked: 0
  };

  const allowed = new Set(Object.keys(actual));

  // ---------------------------------------------
  // 2. Validate tasks individually
  // ---------------------------------------------

  for (let i = 0; i < tasks.length; i++) {
    const t = tasks[i];

    if (!isObj(t)) {
      issues.push(`task ${i + 1} is invalid`);
      continue;
    }

    const id = str(t.task_id);
    const name = str(t.task_name ?? t.name);
    const status = str(t.status);
    const sprint = str(t.sprint);

    if (!id) {
      issues.push(`task ${i + 1} missing task_id`);
    } else if (ids.has(id)) {
      issues.push(`duplicate task_id: ${id}`);
    } else {
      ids.add(id);
    }

    if (!name) {
      issues.push(`task ${id || i + 1} missing name`);
    }

    if (!allowed.has(status)) {
      issues.push(
        `task ${id || i + 1} invalid status: ${status}`
      );
    } else {
      actual[status]++;
    }

    if (!sprint) {
      issues.push(
        `task ${id || i + 1} missing sprint`
      );
    }

    // A source reference can be carried in either
    // the task or the canonical parser adapter.
    if (
      !hasSource(t.evidence) &&
      !hasSource(t.source_reference) &&
      !hasSource(t.source)
    ) {
      // The strict 12-field parser has no task-level
      // citation field. Permit the approved task board
      // as report-level evidence in that contract.
      const hasBoardSource =
        list(o.source_references).some(s =>
          str(s).toLowerCase() ===
          'sample_task_board.csv'
        );

      if (!hasBoardSource) {
        issues.push(
          `task ${id || i + 1} missing source evidence`
        );
      }
    }
  }

  // ---------------------------------------------
  // 3. Resolve and verify task counts
  // ---------------------------------------------

  const legacy = isObj(o.task_counts)
    ? o.task_counts
    : {};

  const hasCanonical =
    Number.isInteger(o.total_tasks) &&
    isObj(o.status_counts);

  const hasLegacy =
    Number.isInteger(legacy.total);

  if (!hasCanonical && !hasLegacy) {
    issues.push('task counts missing');
  }

  const total = hasCanonical
    ? o.total_tasks
    : legacy.total;

  if (total !== tasks.length) {
    issues.push(
      `task total mismatch: reported ${total}, ` +
      `actual ${tasks.length}`
    );
  }

  const canonicalCounts = isObj(o.status_counts)
    ? o.status_counts
    : null;

  if (canonicalCounts) {
    for (const status of allowed) {
      const value = canonicalCounts[status];

      if (
        !Number.isInteger(value) ||
        value < 0 ||
        value !== actual[status]
      ) {
        issues.push(
          `${status} count mismatch: ` +
          `reported ${value}, actual ${actual[status]}`
        );
      }
    }

    const sum = Object.values(canonicalCounts)
      .reduce(
        (n, v) => n + (
          Number.isInteger(v) ? v : 0
        ),
        0
      );

    if (sum !== tasks.length) {
      issues.push(
        'status_counts do not sum to task total'
      );
    }
  }

  // Validate the legacy compatibility counts too,
  // when they are present.
  if (hasLegacy) {
    const mapping = {
      completed: 'Done',
      in_progress: 'In Progress',
      not_started: 'To Do',
      blocked: 'Blocked'
    };

    for (const [field, status] of
      Object.entries(mapping)) {
      if (legacy[field] !== actual[status]) {
        issues.push(
          `task_counts.${field} mismatch`
        );
      }
    }

    if (legacy.total !== tasks.length) {
      issues.push(
        'legacy task_counts total mismatch'
      );
    }
  }

  // ---------------------------------------------
  // 4. Verify requested sprint isolation
  // ---------------------------------------------

  const request = str(ctx.request_text);

  const match = request.match(
    /\bSprint\s+(\d+)\b/i
  );

  const expectedSprint = match
    ? `Sprint ${match[1]}`
    : null;

  const reportedSprint = str(
    o.sprint ??
    o.report_period
  );

  if (expectedSprint) {
    if (
      reportedSprint &&
      reportedSprint.toLowerCase() !==
        expectedSprint.toLowerCase()
    ) {
      issues.push(
        `report sprint mismatch: expected ` +
        expectedSprint
      );
    }

    for (const t of tasks) {
      if (
        str(t?.sprint).toLowerCase() !==
        expectedSprint.toLowerCase()
      ) {
        issues.push(
          `out-of-scope task: ${str(t?.task_id)}`
        );
      }
    }
  } else {
    // No explicit sprint was requested.
    // Do not reject a project-wide report merely
    // because different sprint values occur in tasks.
    if (/^Sprint\s+\d+$/i.test(reportedSprint)) {
      issues.push(
        'unexpected sprint-specific report'
      );
    }
  }

  // ---------------------------------------------
  // 5. Validate blocker reconciliation
  // ---------------------------------------------

  const blockedIds = tasks
    .filter(t => str(t?.status) === 'Blocked')
    .map(t => str(t.task_id));

  const blockers = isArray(o.blockers)
    ? o.blockers
    : o.issues_and_blockers;

  if (!isArray(blockers)) {
    issues.push('blockers array missing');
  } else {
    // Blockers are strings in the authoritative
    // Status Reporter schema.
    const blockerText = blockers.map(b =>
      typeof b === 'string'
        ? b
        : JSON.stringify(b)
    );

    for (const id of blockedIds) {
      const escaped = id.replace(
        /[.*+?^${}()|[\]\\]/g,
        '\\$&'
      );

      const expression = new RegExp(
        `\\b${escaped}\\b`,
        'i'
      );

      if (
        !blockerText.some(text =>
          expression.test(text)
        )
      ) {
        issues.push(
          `blocked task ${id} missing from blockers`
        );
      }
    }

    if (
      blockedIds.length === 0 &&
      blockers.length > 0
    ) {
      issues.push(
        'blockers reported without in-scope blocked tasks'
      );
    }
  }

  // ---------------------------------------------
  // 6. Validate supporting report collections
  // ---------------------------------------------

  if (!isArray(o.highlights)) {
    issues.push('highlights array missing');
  }

  if (!isArray(o.risks)) {
    issues.push('risks array missing');
  }

  if (
    !isArray(o.source_references) ||
    o.source_references.length === 0
  ) {
    issues.push('source_references missing');
  }

  // ---------------------------------------------
  // 7. Validate draft stakeholder update
  // ---------------------------------------------

  const email = isObj(o.email_draft)
    ? o.email_draft
    : null;

  const draft = str(
    o.draft_stakeholder_update ??
    email?.body
  );

  if (!draft) {
    issues.push(
      'draft_stakeholder_update missing'
    );
  } else if (
    !/\bDRAFT\b/i.test(draft) &&
    email?.is_draft !== true
  ) {
    issues.push(
      'stakeholder update not marked DRAFT'
    );
  }

  // ---------------------------------------------
  // 8. Detect out-of-scope task references
  // ---------------------------------------------

  if (expectedSprint) {
    const narrative = [
      summary,
      ...list(o.highlights),
      ...list(blockers),
      ...list(o.risks),
      draft
    ].map(x =>
      typeof x === 'string'
        ? x
        : JSON.stringify(x)
    ).join('\n');

    const mentioned = new Set(
      (
        narrative.match(/\bT\d{3,}\b/gi) || []
      ).map(id => id.toUpperCase())
    );

    for (const id of mentioned) {
      if (!ids.has(id)) {
        issues.push(
          `out-of-scope task reference: ${id}`
        );
      }
    }
  }

  // ---------------------------------------------
  // 9. Final consistency
  // ---------------------------------------------

  if (o.task_counts_validated === false) {
    issues.push(
      'specialist task-count validation failed'
    );
  }

  if (o.task_counts_reconciled === false) {
    issues.push(
      'specialist task reconciliation failed'
    );
  }

  if (o.blocker_reconciliation_pass === false) {
    issues.push(
      'specialist blocker reconciliation failed'
    );
  }

  return [...new Set(issues)];
}

// --------------------------------------------------
// 6. MILESTONE VALIDATION
// --------------------------------------------------

function validateMilestone(o) {
  const issues = [];

  if (!isArray(o.phases)) {
    issues.push('phases array missing');
  } else {
    o.phases.forEach((p, i) => {
      if (!p || typeof p !== 'object') {
        issues.push(
          `phase ${i + 1} is invalid`
        );
        return;
      }

      if (!nonEmpty(p.phase_name)) {
        issues.push(
          `phase ${i + 1} has no name`
        );
      }

      const start = Number(p.start_week);
      const end = Number(p.end_week);

      if (
        !Number.isInteger(start) ||
        !Number.isInteger(end) ||
        start < 1 ||
        end < start
      ) {
        issues.push(
          `phase ${
            p.phase_name || i + 1
          } has invalid week range`
        );
      }

      if (!hasSource(p.source_reference)) {
        issues.push(
          `phase ${
            p.phase_name || i + 1
          } has no source reference`
        );
      }
    });
  }

  if (!isArray(o.milestones)) {
    issues.push('milestones array missing');
  } else {
    o.milestones.forEach((m, i) => {
      if (!m || typeof m !== 'object') {
        issues.push(
          `milestone ${i + 1} is invalid`
        );
        return;
      }

      if (!nonEmpty(m.name)) {
        issues.push(
          `milestone ${i + 1} has no name`
        );
      }

      if (!hasSource(m.source_reference)) {
        issues.push(
          `milestone ${
            m.name || i + 1
          } has no source reference`
        );
      }

      if (
        m.target_week !== null &&
        m.target_week !== undefined &&
        (
          !Number.isInteger(Number(m.target_week)) ||
          Number(m.target_week) < 1
        )
      ) {
        issues.push(
          `milestone ${
            m.name || i + 1
          } has invalid target_week`
        );
      }
    });
  }

  if (!isArray(o.blocked_tasks)) {
    issues.push('blocked_tasks array missing');
  } else {
    o.blocked_tasks.forEach((t, i) => {
      if (!t || typeof t !== 'object') {
        issues.push(
          `blocked task ${i + 1} is invalid`
        );
        return;
      }

      if (!nonEmpty(t.task_id)) {
        issues.push(
          `blocked task ${i + 1} has no task_id`
        );
      }

      if (
        normalizeStatus(t.status) !== 'blocked'
      ) {
        issues.push(
          `blocked task ${
            t.task_id || i + 1
          } has invalid status`
        );
      }

      if (!hasSource(t.source_reference)) {
        issues.push(
          `blocked task ${
            t.task_id || i + 1
          } has no source reference`
        );
      }
    });
  }

  if (!isArray(o.milestone_alerts)) {
    issues.push('milestone_alerts array missing');
  } else {
    o.milestone_alerts.forEach((a, i) => {
      if (!a || typeof a !== 'object') {
        issues.push(
          `milestone alert ${i + 1} is invalid`
        );
        return;
      }

      if (!nonEmpty(a.alert)) {
        issues.push(
          `milestone alert ${i + 1} has no description`
        );
      }

      if (
        !hasSource(a.evidence) &&
        !hasSource(a.source_reference)
      ) {
        issues.push(
          `milestone alert ${i + 1} has no evidence`
        );
      }
    });
  }

  // Null calendar dates are permitted.
  // They must not be fabricated.

  return issues;
}

// --------------------------------------------------
// 7. STAKEHOLDER UPDATE VALIDATION
// --------------------------------------------------


function validateStakeholder(o) {
  const issues = [];

  const isObject = v =>
    v !== null &&
    typeof v === 'object' &&
    !Array.isArray(v);

  const report = isObject(o.stakeholder_update)
    ? o.stakeholder_update
    : isObject(o.update)
      ? o.update
      : o;

  const draft = isObject(report.email_draft)
    ? report.email_draft
    : report;

  const isDraft =
    o.draft_only === true ||
    o.is_draft === true ||
    report.draft_only === true ||
    report.is_draft === true ||
    draft.draft_only === true ||
    draft.is_draft === true;

  if (!isDraft) {
    issues.push('stakeholder update not flagged as draft');
  }

  if (
    !nonEmpty(draft.body) &&
    !nonEmpty(report.body) &&
    !nonEmpty(report.content)
  ) {
    issues.push('stakeholder update body is empty');
  }

  if (
    !nonEmpty(draft.subject) &&
    !nonEmpty(report.subject)
  ) {
    issues.push('stakeholder update subject missing');
  }

  return issues;
}

// --------------------------------------------------
// 8. VALIDATION REGISTRY
// --------------------------------------------------

const checks = {
  plan: validatePlan,
  risk: validateRisk,
  status: validateStatus,
  milestone: validateMilestone,
  stakeholder_update: validateStakeholder
};



// --------------------------------------------------
// 9. BUILD VALIDATION OUTPUT
// --------------------------------------------------

const output = [];

for (const key of wanted) {
  const raw = pick(sources[key]);
