  parsed = parsed.output;
  if (typeof parsed === 'string') parsed = JSON.parse(parsed);
}

const intents = ['plan', 'risk', 'status', 'milestone'];
const decisions = ['ready', 'needs_clarification', 'insufficient_data'];

const intent = intents.includes(parsed.intent)
  ? parsed.intent : 'unknown';

const decision = decisions.includes(parsed.decision)
  ? parsed.decision : 'needs_clarification';

const questions = Array.isArray(parsed.clarification_questions)
  ? parsed.clarification_questions.map(String).filter(Boolean)
  : [];

return [{
  json: {
    ...original,
    intent,
    request_type: intent,
    capabilities: intent,
    decision,
    needs_clarification: decision !== 'ready',
    reason: String(parsed.reason || ''),
    clarification_questions: questions
  }
}];

