const allowed = [
  'plan',
  'risk',
  'status',
  'milestone',
  'stakeholder_update'
];

return $input.all().map(item => {
  const j = item.json;

  let capabilities = j.capabilities;

  // Convert JSON string to array
  if (typeof capabilities === 'string') {
    try {
      capabilities = JSON.parse(capabilities);
    } catch {
      throw new Error(
        'Invalid capabilities JSON'
      );
    }
  }

  // Validate capability array
  if (
    !Array.isArray(capabilities) ||
    capabilities.length === 0 ||
    !capabilities.every(c => allowed.includes(c))
  ) {
    throw new Error(
      'Missing or unsupported capabilities'
    );
  }

  // Preserve all original fields, including trace context
  return {
    json: {
      ...j,

      snapshot_id: j.snapshot_id,
      request_text: j.request_text,

      capabilities: [...new Set(capabilities)],

      intent_status: 'selected',
      intent_source: 'conversational_agent'
    }
  };
});

const input = $json;

const capabilities = Array.isArray(input.capabilities)
  ? input.capabilities
  : [];

const intent = String(
  input.request_type ??
  input.intent ??
  capabilities[0] ??
  ''
).trim().toLowerCase();

const request = String(
  input.request_text ?? ''
).trim();

const questions = [];

const hasDuration =
  /\b\d+\s*(?:-|to\s*)?(?:\d+\s*)?(?:weeks?|months?|days?)\b/i
    .test(request) ||
  /\b\d{4}-\d{2}-\d{2}\b/.test(request);

const hasTaskEvidence =
  input.task_data_available === true;

let message =
  'More information is required to produce a reliable report.';

switch (intent) {

  case 'plan':
    message =
      'The available information is insufficient ' +
      'for a detailed project plan.';

    questions.push(
      'What are the project goals, scope, and expected deliverables?'
    );

    if (!hasDuration) {
      questions.push(
        'What is the target timeline or delivery date?'
      );
    }

    questions.push(
      'What team size and roles are available?'
    );
    break;

  case 'risk':
    message =
      'Additional project details are required ' +
      'for a grounded risk assessment.';

    questions.push(
      'What is the project purpose and scope?'
    );

    questions.push(
      'What are the main activities, technologies, or dependencies?'
    );

    questions.push(
      'Are there known constraints, concerns, or existing risks?'
    );
    break;

  case 'status':
    message = hasTaskEvidence
      ? 'Please clarify the status reporting requirements.'
      : 'No task-level evidence is available in the current ' +
        'authorized context to verify project status.';

    questions.push(
      'Which project and reporting period should be assessed?'
    );

    if (!hasTaskEvidence) {
      questions.push(
        'Can you provide a task board or task status records?'
      );
    }
    break;

  case 'milestone':
    message =
      'More information is needed to assess milestones.';

    questions.push(
      'Which project and reporting period should be assessed?',
      'Can you provide the project timeline and current progress?'
    );
    break;

  case 'stakeholder_update':
    message =
      'More information is needed for a grounded stakeholder update.';

    questions.push(
      'Which project and reporting period should be covered?',
      'Who is the intended audience?',
      'Can you provide relevant progress and blocker information?'
    );
    break;

  default:
    questions.push(
      'Which project are you referring to?',
      'Do you need a plan, risk assessment, status report, or milestone update?'
    );
}

return {
  json: {
    ...input,
    agent: 'orchestrator',
    status: 'needs_clarification',
    message,
    clarification_questions: questions,
    context_authorized:
      input.context_authorized === true,
    report: null
  }
};

const items = $input.all();

return items.map(item => {
  const j = item.json || {};

  const request = String(j.request_text ?? '')
    .trim()
    .replace(/\s+/g, ' ');

  const snapshot = String(j.snapshot_id ?? '').trim();

  let capabilities = j.capabilities ?? [];

  if (typeof capabilities === 'string') {
    try {
      capabilities = JSON.parse(capabilities);
    } catch {
      capabilities = [capabilities];
    }
  }

  capabilities = Array.isArray(capabilities)
    ? capabilities.map(x => String(x).trim().toLowerCase())
    : [];

  const selected =
    j.intent_status === 'selected' &&
    snapshot.length > 0;

  const authorized =
    j.project_selection_confirmed === true ||
    j.context_authorized === true ||
    j.context_authorization_status === 'authorized';

  // Explicit new-project requests
  const newProject =
    /\b(?:new|different|another|unrelated|separate)\s+(?:\w+\s+){0,2}project\b/i
      .test(request);

  // Standalone briefs without a confirmed link
  // to the selected project
  const standaloneBrief =
    /\b(?:project plan|risk assessment)\s+for\s*:\s*["'“]?\s*(?:we|i|our team|our company|the client|a client)\b/i
      .test(request);

  const durationOnly =
    /\b(?:project plan|plan)\s+for\s+(?:a|an)\s+\d+\s*[- ]?\s*(?:day|week|month)s?\s+project\b/i
      .test(request) &&
    !/\b(?:scope includes|deliverables include|objectives are|requirements include)\b/i
      .test(request);

  const insufficientDetails =
    /\b(?:no other details|no further details|without any details|no project details)\b/i
      .test(request);

  const vagueStatus =
    capabilities.includes('status') &&
    /\b(?:status report|project status|weekly status(?: report)?)\s+for\s*:\s*["'“]?/i
      .test(request) &&
    !/\b(?:task board|task status records|sprint\s+\d+|T\d{3}|approved snapshot)\b/i
      .test(request);

  const vagueProgressStatement =
    capabilities.includes('status') &&
    /\b(?:things are going fine|everything is fine|all is well|things look good)\b/i
      .test(request) &&
    !/\b(?:task board|sprint\s+\d+|T\d{3})\b/i
      .test(request);

  const requiresClarification =
    newProject ||
    standaloneBrief ||
    durationOnly ||
    insufficientDetails ||
    vagueStatus ||
    vagueProgressStatement;

  const eligible =
    Boolean(request) &&
    Boolean(snapshot) &&
    (selected || authorized) &&
    !requiresClarification;

  return {
    json: {
      ...j,
      project_context_eligible: Boolean(eligible),
      project_context_decision:
        eligible
          ? 'eligible_for_snapshot_validation'
          : 'requires_clarification',
      project_context_reason:
        requiresClarification
          ? 'Request is unrelated, standalone, or insufficiently specified'
          : !snapshot
            ? 'No selected snapshot'
            : !(selected || authorized)
              ? 'No trusted project selection'
              : 'Request eligible for project validation'
    }
  };
});
